function handleBrickCollision(ball, brick) {
  const cx = ball.x - (brick.x + brick.w / 2);
  const cy = ball.y - (brick.y + brick.h / 2);
  const dx = (brick.w / 2 + ball.r) - Math.abs(cx);
  const dy = (brick.h / 2 + ball.r) - Math.abs(cy);

