    // Side hit
    ball.vx = -ball.vx;
    ball.x += (cx < 0) ? -dx : dx;
  } else if (dy < dx) {
    // Top/Bottom hit
    ball.vy = -ball.vy;
    ball.y += (cy < 0) ? -dy : dy;
  } else {
    // Corner hit
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x += (cx < 0) ? -dx : dx;
    ball.y += (cy < 0) ? -dy : dy;
  }
}
```
