// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick collisions are also handled here to ensure
// precise resolution and prevent tunnelling (sweep emulation via sub-stepping).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-stepping to prevent tunnelling and handle precise brick bounces.
  const subSteps = 10;
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks
    for (const brick of state.bricks) {
      if (!brick.alive) continue;

      if (collides(ball, brick)) {
        // Resolve collision: find the face with the smallest penetration
        const cx = ball.x - (brick.x + brick.w / 2);
        const cy = ball.y - (brick.y + brick.h / 2);
        const dx = (brick.w / 2 + ball.r) - Math.abs(cx);
        const dy = (brick.h / 2 + ball.r) - Math.abs(cy);

        if (dx < dy) {
          // Side hit: flip vx and push out
          ball.vx = -ball.vx;
          ball.x += (cx < 0) ? -dx : dx;
        } else if (dy < dx) {
          // Top/Bottom hit: flip vy and push out
          ball.vy = -ball.vy;
          ball.y += (cy < 0) ? -dy : dy;
        } else {
          // Corner hit: flip both and push out
          ball.vx = -ball.vx;
          ball.vy = -ball.vy;
          ball.x += (cx < 0) ? -dx : dx;
          ball.y += (cy < 0) ? -dy : dy;
        }

        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

